import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getChildApplicationHandler } from "../handlers/getChildApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof getChildApplicationHandler>>;

export function useGetChildApplication(
  teamPk: TeamPartition,
  applicationId: string,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getChildApplication", teamPk, applicationId],
    queryFn: () => getChildApplicationHandler(teamPk, applicationId),
    ...options,
  });
}
